def acceptance(policy):
    return [{"id": t["id"], "req": t["req"], "title": t["title"], "ok": run_test(t, policy)[0]} for t in HIDDEN]

def by_requirement(rows):
    out = {}
    for r in rows:
        p, n = out.get(r["req"], (0, 0))
        out[r["req"]] = (p + int(r["ok"]), n + 1)
    return out

ref_rows, starter_rows = acceptance(MY_POLICY), acceptance(STARTER_POLICY)
ref_by, starter_by = by_requirement(ref_rows), by_requirement(starter_rows)
for q in sorted(ref_by):
    print(f"   {q}: 정책 {ref_by[q][0]}/{ref_by[q][1]} · 기본 {starter_by[q][0]}/{starter_by[q][1]}")
