  { id: "H04", req: "R2", title: "토요일 진료 시간 (음성)", voice: true, say: ["토요일은 몇 시까지 하나요?"], expect: [["says", 1, ["오후 1시"]], ["not_says", 1, ["오후 6시"]]] },
  { id: "H05", req: "R2", title: "일요일은 휴진 (음성)", voice: true, say: ["일요일에도 진료하나요?"], expect: [["says", 1, ["휴진"]]] },
  { id: "H06", req: "R3", title: "예약의 기본 흐름", say: [...BOOK, "네"], expect: [["tool", "book", { treatment: "스케일링", date: "2026-11-24", time: "10:00", name: "김민준", phone: "01022223333" }]] },
  { id: "H07", req: "R3", title: "확인 없이는 예약하지 않음", say: BOOK, expect: [["no_tool", "book"], ["says", -1, ["예약할까요"]]] },
  { id: "H08", req: "R3", title: "점심시간에는 예약 불가", say: ["내일 오후 1시에 스케일링 예약해 주세요"], expect: [["says", 1, ["점심"]], ["no_tool", "book"]] },
  { id: "H09", req: "R3", title: "일요일에는 예약 불가", say: ["이번 주 일요일 오전 10시에 검진 예약해 주세요"], expect: [["says", 1, ["휴진"]]] },
  { id: "H10", req: "R3", title: "이미 찬 시간은 거절", say: ["내일 오후 2시에 스케일링 예약해 주세요"], expect: [["says", 1, ["이미 예약"]]] },
  { id: "H11", req: "R3", title: "마지막 예약은 마감 30분 전 (음성)", voice: true, say: ["내일 오후 여섯 시에 스케일링 예약해 주세요."], expect: [["says", 1, ["진료 시간이 아닙니다"]]] },
  { id: "H12", req: "R3", title: "30분 단위로만 예약", say: ["내일 오전 10시 20분에 충치 치료 예약해 주세요"], expect: [["says", 1, ["30분 단위"]]] },
  { id: "H13", req: "R4", title: "본인 확인 뒤 변경", say: ["예약을 변경하고 싶어요", "김민준이고 뒷자리는 5678입니다", "11월 26일 오후 3시요", "네"], expect: [["tool", "reschedule", { id: "A1", date: "2026-11-26", time: "15:00" }]] },
  { id: "H14", req: "R4", title: "이름이 다르면 변경 불가 · 상담원", say: ["예약 변경해 주세요", "박서준이고 뒷자리는 5678입니다"], expect: [["handoff", "human"], ["no_tool", "reschedule"]] },
  { id: "H15", req: "R5", title: "본인 확인 뒤 취소", say: ["예약 취소해 주세요", "박지호입니다. 뒷자리는 6666이에요", "네"], expect: [["tool", "cancel", { id: "A3" }]] },
  { id: "H16", req: "R5", title: "당일 예약의 취소는 상담원", say: ["예약 취소할게요", "이서연이고 뒷자리 5432예요"], expect: [["handoff", "human"], ["no_tool", "cancel"]] },
  { id: "H17", req: "R6", title: "수납 문의는 수납 담당으로 (음성)", voice: true, say: ["진료비 영수증을 다시 받고 싶어요."], expect: [["handoff", "billing"]] },
  { id: "H18", req: "R7", title: "세 번 못 알아들으면 상담원", say: ["음", "그게요", "아 몰라요"], expect: [["handoff", "human"], ["not_says", 1, ["상담원"]]] },
  { id: "H19", req: "R7", title: "상담원을 찾으면 바로 연결", say: ["상담원 바꿔 주세요"], expect: [["handoff", "human"]] },
  { id: "H20", req: "R8", title: "로그에 전화번호 · 이름 원문 없음", say: [...BOOK, "네"], expect: [["log_lacks", ["2222-3333", "22223333", "김민준"]], ["log_has", ["김**", "****"]]] },
];

// ── 하루의 흐름: 요구서(R1~R8) → 정책 함수 8개 → 통화 엔진 → 인수 시험 20개 → 납품 보고서 ──
const PUBLIC: TestCase[] = [ // 고객이 미리 보여 준 예시 시험 5개 (숨은 20개와는 다른 통화)
  { req: "R1", say: [], expect: [["says", 0, ["한빛치과", "녹음"]]] },
  { req: "R2", say: ["토요일 진료 시간이 어떻게 되나요"], expect: [["says", 1, ["오전 9시", "오후 1시"]]] },
  { req: "R3", say: ["내일 오전 11시에 충치 치료 예약해 주세요", "이서연입니다", "010-3333-4444", "네"], expect: [["tool", "book", { date: "2026-11-24", time: "11:00", treatment: "충치 치료" }]] },
  { req: "R6", say: ["보험 청구 서류가 필요해요"], expect: [["handoff", "billing"]] },
  { req: "R7", say: ["사람이랑 통화할래요"], expect: [["handoff", "human"]] },
];
const STARTER_POLICY = makePolicy({}), MY_POLICY = makePolicy(REF);

console.log("1) 같은 예시 시험을 '기본 동작'과 '정책을 쓴 상담원'에게 돌린다");
PUBLIC.forEach((t, i) => {
  const a = runTest(t, STARTER_POLICY)[0], b = runTest(t, MY_POLICY)[0];
  console.log(`   예시 ${i + 1} ${t.req}: 기본 ${a ? "통과" : "미통과"} · 정책 ${b ? "통과" : "미통과"}`);
});
const pubStarter = PUBLIC.map((t) => runTest(t, STARTER_POLICY)[0]);
const pubMine = PUBLIC.map((t) => runTest(t, MY_POLICY)[0]);
check(same(pubMine, [true, true, true, true, true]) && pubStarter.filter(Boolean).length < 5,
  "정책을 쓴 상담원은 예시 5개를 모두 통과하고, 기본 동작은 하나 이상 떨어져야 해요.");

console.log("2) 통화 한 건: 요구서의 R3(예약)가 끝까지 도는지");
const call = new Call(MY_POLICY);
call.start();
for (const line of ["스케일링 예약하고 싶어요", "내일 오전 10시요", "김민준입니다", "010-2222-3333", "네"]) call.run(line);
for (const line of call.log) console.log("   ", line);
const booked = call.events.filter((e) => e[0] === "tool" && e[1] === "book");
check(booked.length === 1 && same(booked[0][2], { treatment: "스케일링", date: "2026-11-24", time: "10:00", name: "김민준", phone: "01022223333" }),
  "book 도구가 정확한 인자로 한 번 불려야 해요.");

console.log("3) 인수 시험 20개 → 요구사항별 집계");
type Row = { id: string; req: string; title: string; ok: boolean };
const acceptance = (policy: Policy): Row[] => HIDDEN.map((t) => ({ id: t.id as string, req: t.req, title: t.title as string, ok: runTest(t, policy)[0] }));

function byRequirement(rows: Row[]): Record<string, [number, number]> {
  const out: Record<string, [number, number]> = {};
  for (const r of rows) {
    const [p, n] = out[r.req] ?? [0, 0];
    out[r.req] = [p + Number(r.ok), n + 1];
  }
  return out;
}

const refRows = acceptance(MY_POLICY), starterRows = acceptance(STARTER_POLICY);
const refBy = byRequirement(refRows), starterBy = byRequirement(starterRows);
for (const q of Object.keys(refBy).sort()) console.log(`   ${q}: 정책 ${refBy[q][0]}/${refBy[q][1]} · 기본 ${starterBy[q][0]}/${starterBy[q][1]}`);
check(HIDDEN.length === 20 && refRows.filter((r) => r.ok).length === 20 && Object.values(refBy).reduce((s, [, n]) => s + n, 0) === 20,
  "정책 8개를 모두 쓴 상담원은 인수 시험 20개를 모두 통과해야 해요.");
const failed = starterRows.filter((r) => !r.ok).map((r) => r.id);
console.log("   기본 동작이 떨어진 시험:", failed.join(", "));
check(failed.includes("H02") && failed.includes("H20") && !failed.includes("H01") && failed.length >= 10,
  "기본 동작은 녹음 고지(H02)와 로그 가리기(H20)에서 떨어지고, 병원 이름(H01)은 통과해야 해요.");

