function grade(tests: any[]): boolean[] {
  // 좋은 시험의 조건: 모양이 맞고 · 참고 구현은 모두 통과 · 기본 동작은 둘 이상 실패 · 요구사항 3가지 이상
  const good = tests.filter(validTest), ref = makePolicy(REF), starter = makePolicy({});
  return [good.length >= 3, good.filter((t) => runTest(t, ref)[0]).length === good.length, good.filter((t) => !runTest(t, starter)[0]).length >= 2, new Set(good.map((t) => t.req)).size >= 3];
}

