guard.python:
# D46 · Part 3 · 본인 확인과 넘기기 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d46_guard.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않고 손님의 말은 글로 넣음)
#   성함 + 전화번호 뒤 네 자리 본인 확인 · 당일 취소는 상담원 · 세 번 못 알아들으면 상담원 · 수납은 수납 담당
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import re, datetime as dt

TODAY = dt.date(2026, 11, 23)                            # 시험은 늘 이 날을 '오늘'로 봄 (월요일)
WD = "월화수목금토일"
TREAT = {"스케일링": "스케일링", "충치": "충치 치료", "사랑니": "사랑니 발치", "임플란트": "임플란트 상담", "검진": "정기 검진"}
NUM = {"한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "열한": 11, "열두": 12}
MIN = {"십": 10, "이십": 20, "삼십": 30, "사십": 40, "오십": 50}
ORDER = ["treatment", "date", "time", "name", "phone"]
ASK = {"treatment": "어떤 진료를 예약해 드릴까요?", "date": "원하시는 날짜를 말씀해 주세요.", "time": "몇 시가 좋으실까요?",
       "name": "예약하실 분의 성함을 말씀해 주세요.", "phone": "연락받으실 전화번호를 말씀해 주세요."}
WHY = {"closed": "그날은 휴진입니다. 다른 날짜를 말씀해 주세요.", "hours": "그 시간은 진료 시간이 아닙니다. 다른 시간을 말씀해 주세요.",
       "lunch": "그 시간은 점심시간입니다. 다른 시간을 말씀해 주세요.", "unit": "예약은 30분 단위로 받습니다. 정각이나 30분으로 말씀해 주세요.",
       "taken": "그 시간에는 이미 예약이 있습니다. 다른 시간을 말씀해 주세요."}
REASK = ["죄송합니다. 다시 한번 말씀해 주세요.", "잘 알아듣지 못했습니다. 예약, 변경, 취소, 진료 시간 가운데 무엇을 도와드릴까요?"]

def new_db():                                            # 가상의 예약 장부 (시험마다 새로 만듦)
    return {"appts": [{"id": "A1", "name": "김민준", "phone": "01012345678", "treatment": "스케일링", "date": "2026-11-25", "time": "10:00"},
                      {"id": "A2", "name": "이서연", "phone": "01098765432", "treatment": "충치 치료", "date": "2026-11-23", "time": "16:00"},
                      {"id": "A3", "name": "박지호", "phone": "01055556666", "treatment": "정기 검진", "date": "2026-11-24", "time": "14:00"}], "next": 4}

def taken(db, date, time):                               # 그 날짜 · 시각에 이미 예약이 있는가
    return any(a["date"] == date and a["time"] == time for a in db["appts"])

def find_appt(db, last4):                                # 전화번호 뒤 네 자리로 예약 찾기 (없으면 None)
    return next((a for a in db["appts"] if a["phone"][-4:] == last4), None)

def ko_time(hhmm):                                       # "15:30" → "오후 3시 30분"
    h, m = map(int, hhmm.split(":")); ap = "오전" if h < 12 else "오후"; h12 = h if h <= 12 else h - 12
    return f"{ap} {h12}시" + (f" {m}분" if m else "")

def ko_date(iso):                                        # "2026-11-25" → "11월 25일 수요일"
    d = dt.date.fromisoformat(iso); return f"{d.month}월 {d.day}일 {WD[d.weekday()]}요일"

# ── 말에서 정보 뽑기 (받아쓴 글은 띄어쓰기가 없을 수 있으므로 공백을 빼고 찾음) ──
def find_date(text, today=TODAY):
    t = text.replace(" ", "")
    for w, k in (("오늘", 0), ("내일", 1), ("모레", 2)):
        if w in t: return (today + dt.timedelta(days=k)).isoformat()
    m = re.search(r"(이번|다음)주([월화수목금토일])요일", t)
    if m: return (today - dt.timedelta(days=today.weekday()) + dt.timedelta(days=WD.index(m.group(2)) + (7 if m.group(1) == "다음" else 0))).isoformat()
    m = re.search(r"(\d{1,2})월(\d{1,2})일", t)
    if m:
        try: return dt.date(today.year, int(m.group(1)), int(m.group(2))).isoformat()
        except ValueError: return None                    # 없는 날짜("2월 30일")는 '날짜 모름'으로 (원본은 여기서 오류로 멈춤)
    m = re.search(r"([월화수목금토일])요일", t)
    if m: return (today + dt.timedelta(days=(WD.index(m.group(1)) - today.weekday() - 1) % 7 + 1)).isoformat()      # 다가오는 그 요일
    return None

def find_time(text):
    t = text.replace(" ", ""); out = None
    for m in re.finditer(r"(오전|오후|아침|저녁)?(\d{1,2}|열한|열두|다섯|여섯|일곱|여덟|아홉|한|두|세|네|열)시(반|(\d{1,2}|[이삼사오]?십)분)?", t):
        h = int(m.group(2)) if m.group(2).isdigit() else NUM[m.group(2)]
        mi = 30 if m.group(3) == "반" else (int(m.group(4)) if m.group(4) and m.group(4).isdigit() else MIN.get(m.group(4), 0))
        if (m.group(1) in ("오후", "저녁") and h < 12) or (m.group(1) is None and h <= 6): h += 12                    # 그냥 '3시'는 병원 시간으로 15시
        out = f"{h:02d}:{mi:02d}"
    return out

def find_treatment(text):
    return next((v for k, v in TREAT.items() if k in text), None)

def find_name(text, awaiting=False):
    t = text.replace(" ", "")
    SUF = r"(?:이라고합니다|라고합니다|이라고|라고|입니다|이에요|예요|이고|인데요|이요|요)"
    m = re.search(r"(?:이름은|성함은|저는)([가-힣]{2,4}?)" + SUF, t) or ((re.match(r"([가-힣]{2,4}?)" + SUF, t) or re.fullmatch(r"([가-힣]{2,4})[.!?]*", t)) if awaiting else None)
    return m.group(1) if m and m.group(1) not in ("네", "예", "아니", "아니요", "맞아", "글쎄", "그게") else None

def _digits(s): return "".join(str("공일이삼사오육칠팔구".index(c)) if c in "공일이삼사오육칠팔구" else c for c in s.replace("영", "공"))

def find_phone(text):
    t = re.sub(r"\d{1,2}시|\d{1,2}분|\d{1,2}월|\d{1,2}일", "", text.replace(" ", ""))
    m = re.search(r"01\d-?\d{3,4}-?\d{4}", t) or re.search(r"[공영]일[공영일육칠팔구]-?[공영일이삼사오육칠팔구]{3,4}-?[공영일이삼사오육칠팔구]{4}", t)
    return re.sub(r"\D", "", _digits(m.group())) if m else None

def find_last4(text, awaiting=False):
    t = text.replace(" ", "")
    m = re.search(r"(?:끝|뒷|뒤)(?:네)?자리(?:는|가)?(\d{4}|[공영일이삼사오육칠팔구]{4})", t) or (re.search(r"(?<!\d)(\d{4}|[공영일이삼사오육칠팔구]{4})(?!\d)", t) if awaiting else None)
    return _digits(m.group(1)) if m else None

def find_day(text, today=TODAY):                         # 진료 시간을 묻는 말에서 요일 종류: "평일" · "토" · "일" · "공휴일" · None(말하지 않음)
    t = text.replace(" ", "")
    if "공휴일" in t or "빨간날" in t: return "공휴일"
    if "토요일" in t or "주말" in t: return "토"
    if "일요일" in t: return "일"
    if "평일" in t or re.search(r"[월화수목금]요일", t): return "평일"
    for w, k in (("오늘", 0), ("내일", 1), ("모레", 2)):
        if w in t: return ("평일", "평일", "평일", "평일", "평일", "토", "일")[(today + dt.timedelta(days=k)).weekday()]
    return None

def find_intent(text):
    t = text.replace(" ", "")
    if "취소" in t: return "cancel"
    if any(w in t for w in ("변경", "바꾸", "바꿔", "옮기", "옮겨", "미루", "미뤄")): return "change"
    if any(w in t for w in ("진료시간", "몇시까지", "몇시부터", "언제까지", "문여", "진료하", "진료해", "하나요", "하세요", "여나요", "쉬나요")) and "예약" not in t: return "hours"
    if "예약" in t or find_treatment(t): return "book"
    return None

YES, NO = ("네", "예", "맞", "그래", "좋아", "응"), ("아니", "아뇨", "틀려", "틀렸", "그대로두", "그만")
def is_yes(t): return any(w in t.replace("예약", "") for w in YES)   # '예약'의 '예'를 동의로 읽지 않게

class Call:                                              # 통화 한 건. D29의 session.run과 같은 모양: run(손님의 말) → 그 턴에 일어난 일들
    def __init__(self, policy, db=None, today=TODAY):
        self.p, self.db, self.today = policy, db or new_db(), today
        self.s = {"intent": None, "slots": {}, "stage": None, "fails": 0, "appt": None, "who": {}}
        self.log, self.events, self.ended = [], [], None
    def _names(self): return [n for n in (self.s["slots"].get("name"), self.s["who"].get("name"), (self.s["appt"] or {}).get("name")) if n]
    def _out(self, evs):                                 # 이 턴의 일들을 기록 (로그에는 정책의 mask_log를 거친 글만 남김)
        for e in evs:
            self.events.append(e)
            if e[0] == "message": self.log.append("agent: " + self.p["mask_log"](e[1], self._names()))
            elif e[0] == "tool": self.log.append("tool: " + self.p["mask_log"](f"{e[1]} {e[2]}", self._names()))
            elif e[0] == "handoff": self.log.append(f"handoff: {e[1]} · {e[2]}"); self.ended = e[1]
        return evs
    def start(self): return self._out([("message", self.p["greeting"]())])
    def _handoff(self, target, msg, text):
        return [("message", msg), ("handoff", target, "손님의 마지막 말: " + self.p["mask_log"](text, self._names()))]
    def _fail(self, text):
        self.s["fails"] += 1
        if self.p["needs_human"](self.s["fails"], text): return self._handoff("human", "상담원에게 연결해 드리겠습니다. 잠시만 기다려 주세요.", text)
        return [("message", REASK[min(self.s["fails"], len(REASK)) - 1])]
    def _slot_ok(self, sl):                              # 날짜 · 시각이 다 있으면 정책의 check_slot으로 확인 → 안 되면 까닭을 말하고 다시 받음
        code = self.p["check_slot"](sl["date"], sl["time"], self.db)
        if code == "ok": return None
        sl.pop("time", None)
        if code == "closed": sl.pop("date", None)
        return [("message", WHY.get(code, WHY["hours"]))]
    def _verify(self, t, text):                          # 변경 · 취소 전의 본인 확인: 성함 + 전화번호 뒤 네 자리
        who = self.s["who"]; n, l4 = find_name(text, awaiting=True), find_last4(text, awaiting=True)
        if n: who["name"] = n
        if l4: who["last4"] = l4
        if "name" not in who or "last4" not in who:
            if self.s["stage"] == "who" and not (n or l4): return self._fail(text)
            self.s["stage"] = "who"; return [("message", "본인 확인을 위해 예약하신 분의 성함과 전화번호 뒤 네 자리를 말씀해 주세요.")]
        appt = find_appt(self.db, who["last4"])
        if not self.p["verify_caller"](appt, who["name"], who["last4"]):
            return self._handoff("human", "본인 확인이 되지 않았습니다. 상담원에게 연결해 드리겠습니다.", text)
        self.s["appt"], self.s["stage"] = appt, "verified"; return None
    def run(self, text):
        if self.ended: return []
        s, t = self.s, text.replace(" ", "")
        got = {k: v for k, v in (("treatment", find_treatment(t)), ("date", find_date(t, self.today)), ("time", find_time(t)), ("phone", find_phone(t))) if v}
        if s["intent"] == "book" and s.get("ask") == "name" and find_name(text, awaiting=True): got["name"] = find_name(text, awaiting=True)
        elif find_name(text): got["name"] = find_name(text)
        if s["intent"] == "book": s["slots"].update(got)
        nw0 = find_intent(t); eff = nw0 if (nw0 and nw0 != s["intent"] and s["stage"] != "confirm") else s["intent"]
        who_say = find_name(text, awaiting=True) if eff in ("change", "cancel") and (eff != s["intent"] or s["stage"] in (None, "who")) else None   # 본인 확인 발화의 이름도 로그에 쓰기 전에 가림
        self.log.append("user: " + self.p["mask_log"](text, self._names() + ([got["name"]] if "name" in got else []) + ([who_say] if who_say else [])))
        if self.p["needs_human"](s["fails"], text): return self._out(self._handoff("human", "상담원에게 연결해 드리겠습니다. 잠시만 기다려 주세요.", text))
        if self.p["is_billing"](text): return self._out(self._handoff("billing", "수납 담당자에게 연결해 드리겠습니다. 잠시만 기다려 주세요.", text))
        new = find_intent(t)
        if new and new != s["intent"] and s["stage"] != "confirm":
            s.update(intent=new, stage=None, slots=dict(got) if new == "book" else {}, who={}, appt=None); s.pop("ask", None)
        ev = getattr(self, "_" + (s["intent"] or "none"))(t, text, got)
        if not (ev and ev[0][0] == "message" and ev[0][1] in REASK): s["fails"] = 0 if not (ev and ev[-1][0] == "handoff") else s["fails"]
        return self._out(ev)
    def _none(self, t, text, got): return self._fail(text)
    def _hours(self, t, text, got):
        self.s["intent"] = None; return [("message", self.p["hours_answer"](find_day(t, self.today)))]
    def _book(self, t, text, got):
        s, sl = self.s, self.s["slots"]
        if s["stage"] == "confirm":
            if any(w in t for w in NO): s["stage"] = None; sl.pop("time", None); return [("message", "알겠습니다. 원하시는 시간을 다시 말씀해 주세요.")]
            if "date" in got or "time" in got: s["stage"] = None         # 확인 단계에서 날짜 · 시각을 고쳐 말하면 '네'가 섞여 있어도 예약하지 않고 다시 검사
            elif is_yes(t):
                args = {k: sl[k] for k in ORDER}; self.db["appts"].append({"id": f"A{self.db['next']}", **args}); self.db["next"] += 1; s.update(intent=None, stage=None)
                return [("tool", "book", args), ("message", f"예약되었습니다. {ko_date(args['date'])} {ko_time(args['time'])}에 뵙겠습니다.")]
            else:
                if not got: return self._fail(text)
                s["stage"] = None
        if not got and s.get("ask"): return self._fail(text)
        if "date" in sl and "time" in sl:
            bad = self._slot_ok(sl)
            if bad: return bad
        miss = next((k for k in ORDER if k not in sl), None)
        if miss: s["ask"] = miss; return [("message", ASK[miss])]
        s["stage"] = "confirm"; s.pop("ask", None)
        return [("message", f"{ko_date(sl['date'])} {ko_time(sl['time'])}, {sl['treatment']}, {sl['name']} 님으로 예약할까요?")]
    def _change(self, t, text, got):
        s = self.s
        if s["stage"] in (None, "who"):
            bad = self._verify(t, text)
            if bad: return bad
            s["new"] = {}; return [("message", f"{ko_date(s['appt']['date'])} {ko_time(s['appt']['time'])} 예약을 찾았습니다. 언제로 바꿔 드릴까요?")]
        nw = s["new"]
        if s["stage"] == "confirm":
            if any(w in t for w in NO): s["stage"] = "verified"; s["new"] = {}; return [("message", "알겠습니다. 원하시는 날짜와 시간을 다시 말씀해 주세요.")]
            if is_yes(t):
                a = s["appt"]; a.update(date=nw["date"], time=nw["time"]); s.update(intent=None, stage=None)
                return [("tool", "reschedule", {"id": a["id"], "date": nw["date"], "time": nw["time"]}), ("message", f"{ko_date(nw['date'])} {ko_time(nw['time'])}로 변경되었습니다.")]
            return self._fail(text)
        nw.update({k: got[k] for k in ("date", "time") if k in got})
        if not any(k in got for k in ("date", "time")): return self._fail(text)
        if "date" not in nw: return [("message", ASK["date"])]
        if "time" not in nw: return [("message", ASK["time"])]
        bad = self._slot_ok(nw)
        if bad: return bad
        s["stage"] = "confirm"; return [("message", f"{ko_date(nw['date'])} {ko_time(nw['time'])}로 바꿀까요?")]
    def _cancel(self, t, text, got):
        s = self.s
        if s["stage"] in (None, "who"):
            bad = self._verify(t, text)
            if bad: return bad
            a = s["appt"]
            if not self.p["can_cancel"](a["date"], self.today.isoformat()):
                return self._handoff("human", "당일 예약의 취소는 상담원이 도와드립니다. 연결해 드리겠습니다.", text)
            s["stage"] = "confirm"; return [("message", f"{ko_date(a['date'])} {ko_time(a['time'])} {a['treatment']} 예약을 취소할까요?")]
        if any(w in t for w in NO): s.update(intent=None, stage=None); return [("message", "예약을 그대로 두겠습니다.")]
        if is_yes(t):
            a = s["appt"]; self.db["appts"].remove(a); s.update(intent=None, stage=None)
            return [("tool", "cancel", {"id": a["id"]}), ("message", "예약이 취소되었습니다.")]
        return self._fail(text)

# ── 시험 실행기 ──
def run_test(test, policy, speak=None):                  # 시험 하나를 돌려 (통과했는가, 통화 기록)을 돌려줌. speak: 글 → (전화 음질의 소리를 받아쓴) 글
    call = Call(policy); turns = [call.start()]
    for u in test["say"]:
        turns.append(call.run(speak(u) if test.get("voice") and speak else u))
    return all(_check(c, turns, call) for c in test["expect"]), call

def _check(c, turns, call):
    kind = c[0]; msgs = lambda evs: " ".join(e[1] for e in evs if e[0] == "message"); allev = [e for tn in turns for e in tn]
    if kind in ("says", "not_says"):
        said = msgs(allev) if c[1] == "any" else msgs(turns[c[1]]) if -len(turns) <= c[1] < len(turns) else ""
        return all(x in said for x in c[2]) if kind == "says" else not any(x in said for x in c[2])
    if kind == "tool": return any(e[0] == "tool" and e[1] == c[1] and all(e[2].get(k) == v for k, v in c[2].items()) for e in allev)
    if kind == "no_tool": return not any(e[0] == "tool" and e[1] == c[1] for e in allev)
    if kind == "handoff": return any(e[0] == "handoff" and e[1] == c[1] for e in allev)
    if kind == "no_handoff": return not any(e[0] == "handoff" for e in allev)
    if kind == "log_lacks": return not any(x in line for line in call.log for x in c[1])
    if kind == "log_has": return all(any(x in line for line in call.log) for x in c[1])
    raise ValueError(f"모르는 확인 종류: {kind}")

def _valid_check(c):                                     # 확인 한 줄의 모양이 맞는가 (says 의 검색어 목록이 비면 아무 말에나 통과하므로 안 됨)
    if not isinstance(c, (tuple, list)) or len(c) == 0: return False
    words = lambda x: isinstance(x, (list, tuple)) and len(x) >= 1 and all(isinstance(w, str) and w for w in x)
    k = c[0]
    if k in ("says", "not_says"): return len(c) == 3 and (c[1] == "any" or (isinstance(c[1], int) and not isinstance(c[1], bool))) and words(c[2])
    if k == "tool": return len(c) == 3 and isinstance(c[1], str) and isinstance(c[2], dict)
    if k == "no_tool": return len(c) == 2 and isinstance(c[1], str)
    if k == "handoff": return len(c) == 2 and c[1] in ("human", "billing")
    if k == "no_handoff": return len(c) == 1
    if k in ("log_lacks", "log_has"): return len(c) == 2 and words(c[1])
    return False

def valid_test(t):                                       # 시험의 모양이 맞는가
    return (isinstance(t, dict) and isinstance(t.get("req"), str) and isinstance(t.get("say"), list) and all(isinstance(u, str) for u in t["say"])
            and isinstance(t.get("expect"), list) and len(t["expect"]) >= 1 and all(_valid_check(c) for c in t["expect"]))

STARTER = {                                              # 아직 쓰지 않은 정책의 자리를 맡는 '기본 동작' (일부러 허술함)
    "greeting": lambda: "안녕하세요. 한빛치과입니다. 무엇을 도와드릴까요?",
    "hours_answer": lambda day: "진료 시간은 오전 9시부터 오후 6시까지입니다.",
    "check_slot": lambda date, time, db: "ok",
    "needs_human": lambda fails, text: False,
    "verify_caller": lambda appt, name, last4: appt is not None,
    "is_billing": lambda text: False,
    "mask_log": lambda text, names=(): text,
    "can_cancel": lambda appt_date, today: True}

def make_policy(funcs):                                  # 내가 쓴 함수가 None(아직 안 씀)을 돌려주면 기본 동작으로 대신함 → 통화는 늘 끝까지 감
    def wrap(name):
        mine = funcs.get(name)
        def f(*a, **k):
            try: r = mine(*a, **k) if mine else None
            except Exception: r = None
            return STARTER[name](*a, **k) if r is None or r is Ellipsis else r
        return f
    return {name: wrap(name) for name in STARTER}

def greeting():
    return "안녕하세요. 한빛치과 AI 상담원 하나입니다. 이 통화는 상담 품질 향상을 위해 녹음됩니다. 무엇을 도와드릴까요?"

def hours_answer(day):
    table = {"평일": "평일은 오전 9시부터 오후 6시까지 진료하고, 점심시간은 오후 1시부터 오후 2시까지입니다.",
             "토": "토요일은 오전 9시부터 오후 1시까지 진료하며 점심시간은 없습니다.",
             "일": "일요일은 휴진입니다.", "공휴일": "공휴일은 휴진입니다."}
    if day is None:
        return table["평일"] + " " + table["토"] + " 일요일과 공휴일은 휴진입니다."
    return table[day]

HOLIDAYS = {"2026-12-25", "2027-01-01"}   # 공휴일(휴진): 요구서 R2 · 실제 병원이면 달력에서 가져옴

def check_slot(date, time, db):
    wd = dt.date.fromisoformat(date).weekday(); h, m = map(int, time.split(":")); t = h * 60 + m
    if wd == 6 or date in HOLIDAYS: return "closed"
    last = 12 * 60 + 30 if wd == 5 else 17 * 60 + 30
    if t < 9 * 60 or t > last: return "hours"
    if wd < 5 and 13 * 60 <= t < 14 * 60: return "lunch"
    if m not in (0, 30): return "unit"
    if taken(db, date, time): return "taken"
    return "ok"

def needs_human(fails, text):
    t = text.replace(" ", "")
    return fails >= 3 or any(w in t for w in ("상담원", "사람", "직원"))

def verify_caller(appt, name, last4):
    return appt is not None and appt["name"] == name and appt["phone"][-4:] == last4

def is_billing(text):
    t = text.replace(" ", "")
    return any(w in t for w in ("수납", "결제", "영수증", "환불", "보험", "진료비"))

def mask_log(text, names=()):
    text = re.sub(r"(01\d)-?\d{3,4}-?(\d{4})", r"\1-****-\2", text)
    for n in names:
        text = text.replace(n, n[0] + "*" * (len(n) - 1))
    return text

def can_cancel(appt_date, today):
    return appt_date > today

