  { id: "H18", req: "R7", title: "세 번 못 알아들으면 상담원", say: ["음", "그게요", "아 몰라요"], expect: [["handoff", "human"], ["not_says", 1, ["상담원"]]] },
  { id: "H19", req: "R7", title: "상담원을 찾으면 바로 연결", say: ["상담원 바꿔 주세요"], expect: [["handoff", "human"]] },
  { id: "H20", req: "R8", title: "로그에 전화번호 · 이름 원문 없음", say: [...BOOK, "네"], expect: [["log_lacks", ["2222-3333", "22223333", "김민준"]], ["log_has", ["김**", "****"]]] },
];

// ── 본인 확인과 넘기기: 변경 · 취소 전에 확인하고, 안 되면 사람에게 넘긴다 (T4 · T5 · T6 · T8) ──
function talk(policy: Policy, lines: string[]): [Call, Ev[][]] {
  const c = new Call(policy);
  c.start();
  return [c, lines.map((x) => c.run(x))];
}
const hasEvent = (c: Call, ev: Ev): boolean => c.events.some((e) => same(e, ev));

const db = newDb();
const A1 = db.appts[0]; // 김민준 · 010-1234-5678 · 11월 25일 10:00

console.log("1) 본인 확인: 예약이 있고 · 성함이 같고 · 뒤 네 자리가 같을 때만");
const VERIFY: [[Appt | null, string, string], boolean][] = [[[A1, "김민준", "5678"], true], [[A1, "박서준", "5678"], false], [[A1, "김민준", "0000"], false], [[null, "김민준", "5678"], false]];
for (const [args, want] of VERIFY) console.log(`   ${args[1]} · ${args[2]} · 예약 ${args[0] ? "있음" : "없음"} → ${verifyCaller(...args)} (기대 ${want})`);
check(VERIFY.length === 4 && same(VERIFY.map(([a]) => verifyCaller(...a)), VERIFY.map(([, w]) => w)) && findAppt(db, "5678") === A1 && findAppt(db, "9999") === null,
  "성함과 뒤 네 자리가 둘 다 맞아야만 통과해야 해요(하나만 맞으면 안 됨).");

console.log("2) 말에서 성함과 뒤 네 자리 뽑기");
const SAID: [string, string, string][] = [["김민준이고 뒷자리는 5678입니다", "김민준", "5678"], ["이서연이고 뒷자리 5432예요", "이서연", "5432"], ["박지호입니다. 뒷자리는 육육육육이에요", "박지호", "6666"]];
for (const [text] of SAID) console.log(`   ${text} → ${findName(text, true)} · ${findLast4(text, true)}`);
check(SAID.length === 3 && same(SAID.map(([t]) => [findName(t, true), findLast4(t, true)]), SAID.map(([, n, l]) => [n, l])),
  "성함과 숫자(글자로 읽은 숫자 포함)를 말에서 뽑아야 해요.");

console.log("3) 본인 확인 뒤 변경 / 이름이 다르면 상담원");
const [okCall] = talk(makePolicy(REF), ["예약을 변경하고 싶어요", "김민준이고 뒷자리는 5678입니다", "11월 26일 오후 3시요", "네"]);
const [badCall] = talk(makePolicy(REF), ["예약 변경해 주세요", "박서준이고 뒷자리는 5678입니다"]);
const [looseCall, looseTurns] = talk(makePolicy({}), ["예약 변경해 주세요", "박서준이고 뒷자리는 5678입니다"]);
console.log("   확인된 손님:", JSON.stringify(okCall.events.filter((e) => e[0] === "tool").map((e) => e.slice(0, 2))), "→ 장부", okCall.db.appts[0].date, okCall.db.appts[0].time);
console.log("   다른 사람:", badCall.ended, "· 기본 동작:", looseCall.ended);
check(hasEvent(okCall, ["tool", "reschedule", { id: "A1", date: "2026-11-26", time: "15:00" }]) && okCall.db.appts[0].date === "2026-11-26"
  && badCall.ended === "human" && badCall.db.appts[0].date === "2026-11-25" && !badCall.events.some((e) => e[0] === "tool")
  && looseCall.ended === null && looseTurns[looseTurns.length - 1][0][1].includes("찾았습니다"),
  "정책을 쓰면 이름이 다른 사람은 상담원으로 넘어가고, 기본 동작은 그냥 변경해 버리는 허술함을 보여야 해요.");

console.log("4) 취소: 하루 전까지는 AI가, 당일(과 지난 예약)은 상담원이");
const CAN: [[string, string], boolean][] = [[["2026-11-25", "2026-11-23"], true], [["2026-11-24", "2026-11-23"], true], [["2026-11-23", "2026-11-23"], false], [["2026-11-20", "2026-11-23"], false]];
console.log("  ", JSON.stringify(CAN.map(([a]) => canCancel(...a))));
const [tomorrow] = talk(makePolicy(REF), ["예약 취소해 주세요", "박지호입니다. 뒷자리는 6666이에요", "네"]);
const [todayCall] = talk(makePolicy(REF), ["예약 취소할게요", "이서연이고 뒷자리 5432예요"]);
check(same(CAN.map(([a]) => canCancel(...a)), CAN.map(([, w]) => w)) && hasEvent(tomorrow, ["tool", "cancel", { id: "A3" }]) && tomorrow.db.appts.length === 2
  && todayCall.ended === "human" && todayCall.db.appts.length === 3 && !todayCall.events.some((e) => e[0] === "tool"),
  "내일 예약은 취소 도구가 불려 장부에서 빠지고, 오늘 예약은 도구 없이 human으로 넘어가야 해요.");

console.log("5) 넘기기: 세 번 연달아 못 알아들으면 · 상담원을 찾으면 · 수납 문의면");
const NEEDS: [[number, string], boolean][] = [[[0, "상담원 바꿔 주세요"], true], [[0, "사람이랑 통화할래요"], true], [[0, "직원 연결"], true], [[1, "예약하고 싶어요"], false], [[2, "음"], false], [[3, "음"], true]];
console.log("  ", JSON.stringify(NEEDS.map(([a]) => needsHuman(...a))));
const [failCall, failTurns] = talk(makePolicy(REF), ["음", "그게요", "아 몰라요"]);
const [billCall] = talk(makePolicy(REF), ["진료비 영수증을 다시 받고 싶어요"]);
check(same(NEEDS.map(([a]) => needsHuman(...a)), NEEDS.map(([, w]) => w))
  && failCall.ended === "human" && same(failTurns[0].map((e) => e[0]), ["message"]) && same(failTurns[1].map((e) => e[0]), ["message"]) && failTurns[2][failTurns[2].length - 1][0] === "handoff"
  && billCall.ended === "billing" && isBilling("환불해 주세요") && !isBilling("스케일링 예약하고 싶어요"),
  "연달아 세 번째에서야 human으로 넘기고, 수납 말이 나오면 billing으로 넘겨야 해요.");

