print("2) 정책 하나를 안 쓰면 어떤 시험이 떨어지나 (정책마다 지켜 주는 시험이 있어야 한다)")
EXPECT = {"greeting": ["H02"], "is_billing": ["H17"], "can_cancel": ["H16"], "mask_log": ["H20"], "needs_human": ["H18", "H19"]}
got = {name: failed_ids(without(name)) for name in REF}
for name, ids in got.items():
    print(f"   {name:<14} 빼면 → {', '.join(ids) or '(없음!)'}")
