      "정책 8개 모두 빼면 떨어지는 시험이 있어야 하고, 인사 · 수납 · 취소 · 로그 · 연결은 정해진 시험에서 떨어져야 해요.")

print("3) 정책을 조금만 틀리게 쓰면 잡히는가 (변이 시험)")
def mutate(name, fn):
    return make_policy({**REF, name: fn})

MUTANTS = {
    "평일 마지막 예약을 마감 시각(18:00)으로": ("check_slot", lambda d, t, db: "ok" if t == "18:00" else check_slot(d, t, db), "H11"),
