    "점심시간에 토요일도 포함": ("check_slot", lambda d, t, db: "lunch" if t == "13:00" and dt.date.fromisoformat(d).weekday() == 5 else check_slot(d, t, db), "H11"),
}
caught = {}
for what, (name, fn, _) in MUTANTS.items():
    caught[what] = failed_ids(mutate(name, fn))
    print(f"   {what} → {', '.join(caught[what]) or '못 잡음!'}")
