print("4) 요구사항별 집계")
def by_requirement(rows):
    out = {}
    for r in rows:
        p, n = out.get(r["req"], (0, 0))
        out[r["req"]] = (p + int(r["ok"]), n + 1)
    return out

partial = by_requirement(acceptance(without("mask_log", "can_cancel")))
