  { id: "H17", req: "R6", title: "수납 문의는 수납 담당으로 (음성)", voice: true, say: ["진료비 영수증을 다시 받고 싶어요."], expect: [["handoff", "billing"]] },
  { id: "H18", req: "R7", title: "세 번 못 알아들으면 상담원", say: ["음", "그게요", "아 몰라요"], expect: [["handoff", "human"], ["not_says", 1, ["상담원"]]] },
  { id: "H19", req: "R7", title: "상담원을 찾으면 바로 연결", say: ["상담원 바꿔 주세요"], expect: [["handoff", "human"]] },
  { id: "H20", req: "R8", title: "로그에 전화번호 · 이름 원문 없음", say: [...BOOK, "네"], expect: [["log_lacks", ["2222-3333", "22223333", "김민준"]], ["log_has", ["김**", "****"]]] },
];

// ── 인수 시험: 숨은 20개를 돌려 받을지 말지 정한다 (고객은 코드를 읽지 않는다) ──
type Row = { id: string; req: string; title: string; ok: boolean };
const acceptance = (policy: Policy): Row[] => HIDDEN.map((t) => ({ id: t.id as string, req: t.req, title: t.title as string, ok: runTest(t, policy)[0] }));
const failedIds = (policy: Policy): string[] => acceptance(policy).filter((r) => !r.ok).map((r) => r.id);
const without = (...names: string[]): Policy => makePolicy(Object.fromEntries(Object.entries(REF).filter(([k]) => !names.includes(k)))); // 그 정책만 안 쓴 상담원

console.log("1) 시험 자체가 맞는가: 고객의 참고 구현은 20개를 모두 통과해야 한다");
const rows = acceptance(makePolicy(REF));
console.log(`   참고 구현 ${rows.filter((r) => r.ok).length} / ${rows.length}`);
check(HIDDEN.length === 20 && new Set(HIDDEN.map((t) => t.id)).size === 20 && rows.length === 20 && rows.every((r) => r.ok) && rows.filter((r) => r.ok).length === 20,
  "참고 구현이 20개를 모두 통과해야 시험이 맞는 시험이에요(시험 20개가 서로 다른 번호인지도 확인).");

console.log("2) 정책 하나를 안 쓰면 어떤 시험이 떨어지나 (정책마다 지켜 주는 시험이 있어야 한다)");
const EXPECT: Record<string, string[]> = { greeting: ["H02"], is_billing: ["H17"], can_cancel: ["H16"], mask_log: ["H20"], needs_human: ["H18", "H19"] };
const got: Record<string, string[]> = {};
for (const name of Object.keys(REF)) got[name] = failedIds(without(name));
for (const [name, ids] of Object.entries(got)) console.log(`   ${name.padEnd(14)} 빼면 → ${ids.join(", ") || "(없음!)"}`);
check(Object.values(got).every((ids) => ids.length >= 1) && Object.keys(got).length === 8 && Object.entries(EXPECT).every(([n, ids]) => same(got[n], ids)),
  "정책 8개 모두 빼면 떨어지는 시험이 있어야 하고, 인사 · 수납 · 취소 · 로그 · 연결은 정해진 시험에서 떨어져야 해요.");

console.log("3) 정책을 조금만 틀리게 쓰면 잡히는가 (변이 시험)");
const mutate = (name: string, fn: (...a: any[]) => any): Policy => makePolicy({ ...REF, [name]: fn });
const MUTANTS: Record<string, [string, (...a: any[]) => any]> = {
  "평일 마지막 예약을 마감 시각(18:00)으로": ["check_slot", (d: string, t: string, db: Db) => (t === "18:00" ? "ok" : checkSlot(d, t, db))],
  "본인 확인에서 이름을 안 봄": ["verify_caller", (appt: Appt | null) => appt !== null],
  "연결 기준을 네 번째로": ["needs_human", (fails: number, text: string) => fails >= 4 || text.includes("상담원")],
  "점심시간에 토요일도 포함": ["check_slot", (d: string, t: string, db: Db) => (t === "13:00" && weekday(d) === 5 ? "lunch" : checkSlot(d, t, db))],
};
const caught: Record<string, string[]> = {};
for (const [what, [name, fn]] of Object.entries(MUTANTS)) {
  caught[what] = failedIds(mutate(name, fn));
  console.log(`   ${what} → ${caught[what].join(", ") || "못 잡음!"}`);
}
check(same(caught["평일 마지막 예약을 마감 시각(18:00)으로"], ["H11"]) && same(caught["본인 확인에서 이름을 안 봄"], ["H14"]) && same(caught["연결 기준을 네 번째로"], ["H18"]),
  "틀린 정책은 그것을 지키는 시험(H11 · H14 · H18)에서 정확히 잡혀야 해요.");
console.log("   토요일 13:00은 원래 'hours'(진료 시간 밖)라 점심 변이는 어떤 시험에도 안 걸림:", JSON.stringify(caught["점심시간에 토요일도 포함"]));
check(caught["점심시간에 토요일도 포함"].length === 0, "인수 시험에 없는 상황(토요일 13:00)은 틀려도 못 잡아요 — 그래서 보고서에 '확인하지 못한 것'을 적어요.");

console.log("4) 요구사항별 집계");
function byRequirement(rs: Row[]): Record<string, [number, number]> {
  const out: Record<string, [number, number]> = {};
  for (const r of rs) {
    const [p, n] = out[r.req] ?? [0, 0];
    out[r.req] = [p + Number(r.ok), n + 1];
  }
  return out;
}
const partial = byRequirement(acceptance(without("mask_log", "can_cancel")));
console.log("  ", Object.keys(partial).sort().map((q) => `${q} ${partial[q][0]}/${partial[q][1]}`).join(" · "));
check(same(partial, { R1: [2, 2], R2: [3, 3], R3: [7, 7], R4: [2, 2], R5: [1, 2], R6: [1, 1], R7: [2, 2], R8: [0, 1] }) && Object.values(partial).reduce((s, [, n]) => s + n, 0) === 20,
  "취소 규정(can_cancel)과 로그 가리기(mask_log)를 빼면 R5는 1/2, R8은 0/1이어야 하고 합은 20이어야 해요.");

report.python:
# D46 · Part 4 · 납품 보고서 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
