def acceptance(policy):
    return [{"id": t["id"], "req": t["req"], "title": t["title"], "ok": run_test(t, policy)[0]} for t in HIDDEN]

def by_requirement(rows):
    out = {}
    for r in rows:
        p, n = out.get(r["req"], (0, 0))
        out[r["req"]] = (p + int(r["ok"]), n + 1)
    return out

# 로그 가리기(T7)와 취소 규정(T8)을 아직 못 쓴 채로 납품한다고 하자
policy = make_policy({k: v for k, v in REF.items() if k not in ("mask_log", "can_cancel")})
SUBMITS = 1
rows = acceptance(policy)
by = by_requirement(rows)
passed = sum(r["ok"] for r in rows)
NOTES = {"미통과의 원인": "R5 — 당일 예약도 자동으로 취소했다 · R8 — 통화 기록에 이름과 번호가 그대로 남았다",
         "확인하지 못한 것": "실제 전화 음질(8 kHz)에서의 받아쓰기 · 실제 사람의 목소리 · 인수 시험에 없는 상황",
         "고객에게 되물을 것": "거절할 때 가까운 빈 시간을 제안할까요?"}
