table = "".join(f"<tr><td>{html.escape(r['id'])}</td><td>{r['req']}</td><td>{html.escape(r['title'])}</td><td>{'통과' if r['ok'] else '미통과'}</td></tr>" for r in rows)
req_rows = "".join(f"<tr><td>{q}</td><td>{p} / {n}</td><td>{'지킴' if p == n else '미흡'}</td></tr>" for q, (p, n) in sorted(by.items()))
notes = "".join(f"<div><b>{html.escape(k)}</b><br>{html.escape(v)}</div>" for k, v in NOTES.items())
page = (f'<!doctype html><html lang="ko"><meta charset="utf-8"><title>납품 보고서: 한빛치과 AI 콜센터</title>'
        f"<h1>납품 보고서: 한빛치과 AI 콜센터</h1><p>{passed} / 20 인수 시험 통과 · 납품 {SUBMITS}번째 · 시험 속의 오늘 {TODAY}</p>"
        f"<h2>요구사항별</h2><table>{req_rows}</table><h2>인수 시험 20건</h2><table>{table}</table><h2>개발팀의 메모</h2>{notes}</html>")
with open("delivery_report.html", "w", encoding="utf-8") as f:
    f.write(page)
