    json.dump({"passed": passed, "total": len(rows), "submits": SUBMITS, "by_requirement": {q: list(v) for q, v in by.items()},
               "failed": [r["id"] for r in rows if not r["ok"]], "notes": NOTES}, f, ensure_ascii=False, indent=1)

# 만든 파일을 다시 읽어 확인 (파일이 있다는 것만이 아니라 내용이 결과와 맞는지)
