function greeting(): string {
  return "안녕하세요. 한빛치과 AI 상담원 하나입니다. 이 통화는 상담 품질 향상을 위해 녹음됩니다. 무엇을 도와드릴까요?";
}

function hoursAnswer(day: string | null): string {
  const table: Record<string, string> = {
    "평일": "평일은 오전 9시부터 오후 6시까지 진료하고, 점심시간은 오후 1시부터 오후 2시까지입니다.",
    "토": "토요일은 오전 9시부터 오후 1시까지 진료하며 점심시간은 없습니다.",
    "일": "일요일은 휴진입니다.", "공휴일": "공휴일은 휴진입니다." };
  if (day === null) return table["평일"] + " " + table["토"] + " 일요일과 공휴일은 휴진입니다.";
  return table[day];
}

const HOLIDAYS = ["2026-12-25", "2027-01-01"]; // 공휴일(휴진): 요구서 R2 · 실제 병원이면 달력에서 가져옴

function checkSlot(date: string, time: string, db: Db): string {
  const wd = weekday(date); const [h, m] = time.split(":").map(Number); const t = h * 60 + m;
  if (wd === 6 || HOLIDAYS.includes(date)) return "closed";
  const last = wd === 5 ? 12 * 60 + 30 : 17 * 60 + 30;
  if (t < 9 * 60 || t > last) return "hours";
  if (wd < 5 && 13 * 60 <= t && t < 14 * 60) return "lunch";
  if (m !== 0 && m !== 30) return "unit";
  if (taken(db, date, time)) return "taken";
  return "ok";
}

function needsHuman(fails: number, text: string): boolean {
  const t = squeeze(text);
  return fails >= 3 || ["상담원", "사람", "직원"].some((w) => t.includes(w));
}

function verifyCaller(appt: Appt | null, name: string, last4: string): boolean {
  return appt !== null && appt.name === name && appt.phone.slice(-4) === last4;
}

function isBilling(text: string): boolean {
  const t = squeeze(text);
  return ["수납", "결제", "영수증", "환불", "보험", "진료비"].some((w) => t.includes(w));
}

function maskLog(text: string, names: string[] = []): string {
  let out = text.replace(/(01\d)-?\d{3,4}-?(\d{4})/g, "$1-****-$2");
  for (const n of names) out = out.split(n).join(n[0] + "*".repeat(n.length - 1));
  return out;
}

function canCancel(apptDate: string, today: string): boolean {
  return apptDate > today;
}

