// ── 납품 보고서: 인수 시험 결과 → 요구사항별 집계 → delivery.json · delivery_report.html ──
import { readFileSync, statSync, writeFileSync } from "node:fs";

type Row = { id: string; req: string; title: string; ok: boolean };
const acceptance = (policy: Policy): Row[] => HIDDEN.map((t) => ({ id: t.id as string, req: t.req, title: t.title as string, ok: runTest(t, policy)[0] }));
const esc = (s: string): string => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

function byRequirement(rs: Row[]): Record<string, [number, number]> {
  const out: Record<string, [number, number]> = {};
  for (const r of rs) {
    const [p, n] = out[r.req] ?? [0, 0];
    out[r.req] = [p + Number(r.ok), n + 1];
  }
  return out;
}

// 로그 가리기(T7)와 취소 규정(T8)을 아직 못 쓴 채로 납품한다고 하자
