const table = rows.map((r) => `<tr><td>${esc(r.id)}</td><td>${r.req}</td><td>${esc(r.title)}</td><td>${r.ok ? "통과" : "미통과"}</td></tr>`).join("");
const reqRows = Object.keys(by).sort().map((q) => `<tr><td>${q}</td><td>${by[q][0]} / ${by[q][1]}</td><td>${by[q][0] === by[q][1] ? "지킴" : "미흡"}</td></tr>`).join("");
const notes = Object.entries(NOTES).map(([k, v]) => `<div><b>${esc(k)}</b><br>${esc(v)}</div>`).join("");
const page = `<!doctype html><html lang="ko"><meta charset="utf-8"><title>납품 보고서: 한빛치과 AI 콜센터</title>`
  + `<h1>납품 보고서: 한빛치과 AI 콜센터</h1><p>${passed} / 20 인수 시험 통과 · 납품 ${SUBMITS}번째 · 시험 속의 오늘 ${TODAY}</p>`
  + `<h2>요구사항별</h2><table>${reqRows}</table><h2>인수 시험 20건</h2><table>${table}</table><h2>개발팀의 메모</h2>${notes}</html>`;
writeFileSync("delivery_report.html", page, "utf-8");
writeFileSync("delivery.json", JSON.stringify({ passed, total: rows.length, submits: SUBMITS, by_requirement: by, failed: rows.filter((r) => !r.ok).map((r) => r.id), notes: NOTES }, null, 1), "utf-8");

// 만든 파일을 다시 읽어 확인 (파일이 있다는 것만이 아니라 내용이 결과와 맞는지)
const saved = JSON.parse(readFileSync("delivery.json", "utf-8"));
const savedHtml = readFileSync("delivery_report.html", "utf-8");
console.log("저장한 delivery.json:", JSON.stringify({ passed: saved.passed, total: saved.total, failed: saved.failed }));
check(statSync("delivery.json").size > 0 && saved.total === 20 && saved.passed === 18 && same(saved.failed, ["H16", "H20"]) && Object.keys(saved.notes).length === 3,
  "저장한 JSON을 다시 읽으면 20개 중 18개 통과, 미통과는 H16 · H20이어야 해요.");
check(same(saved.by_requirement.R5, [1, 2]) && same(saved.by_requirement.R8, [0, 1]) && (Object.values(saved.by_requirement) as number[][]).reduce((s, [, n]) => s + n, 0) === 20
  && savedHtml.split("<tr><td>H").length - 1 === 20 && savedHtml.includes("18 / 20") && savedHtml.split("미통과").length - 1 === 2 + 1,
  "보고서 HTML에는 인수 시험 20줄과 '18 / 20'이 있고, 미통과 표시는 시험 2줄과 판정 1칸이어야 해요.");

