# ── 정리 퀴즈: 오늘 배운 규칙 8문항, 정답은 모두 코드를 돌려 얻은 값과 비교 ──
empty = new_db()
STARTER_POLICY = make_policy({})
TIMES = [f"{h:02d}:{m:02d}" for h in range(8, 19) for m in (0, 30)]

def sat_last():
    return max(t for t in TIMES if check_slot("2026-11-28", t, empty) == "ok")

def lunch_times():
    return [t for t in TIMES if check_slot("2026-11-24", t, empty) == "lunch"]

def starter_failures():
    return sum(not run_test(t, STARTER_POLICY)[0] for t in HIDDEN)

def fails_to_handoff():
    return next(f for f in range(10) if needs_human(f, "음"))

QUIZ = [
    ("Q1. 토요일에 받는 마지막 예약 시각은?", "12:30", sat_last),
    ("Q2. 평일에 '점심시간'으로 거절되는 시각은? (30분 단위)", ["13:00", "13:30"], lunch_times),
    ("Q3. 시험 속의 오늘(2026-11-23)은 무슨 요일?", "월", lambda: WD[TODAY.weekday()]),
    ("Q4. 오늘 예약(11월 23일)을 AI가 자동으로 취소해도 될까?", False, lambda: can_cancel("2026-11-23", TODAY.isoformat())),
    ("Q5. 손님의 말을 연달아 몇 번 알아듣지 못하면 상담원에게 넘기나?", 3, fails_to_handoff),
    ("Q6. mask_log('010-1234-5678 김민준', ['김민준']) 의 결과는?", "010-****-5678 김**", lambda: mask_log("010-1234-5678 김민준", ["김민준"])),
    ("Q7. 정책을 하나도 안 쓴 기본 동작은 인수 시험 20개 중 몇 개에서 떨어지나?", 15, starter_failures),
    ("Q8. '진료비가 궁금해요'는 누구에게 넘기나? (human / billing / 안 넘김)", "billing", lambda: "billing" if is_billing("진료비가 궁금해요") else ("human" if needs_human(0, "진료비가 궁금해요") else "안 넘김")),
]
score = 0
for q, want, compute in QUIZ:
    got = compute()
    score += got == want
    print(f"{'O' if got == want else 'X'} {q}  → {got}")
print(f"정리 퀴즈 {score} / {len(QUIZ)}")
check(len(QUIZ) == 8 and score == 8, "퀴즈 8문항의 정답이 코드를 돌려 얻은 값과 모두 같아야 해요.")

