//   오늘 배운 규칙을 퀴즈 8문항으로, 정답은 모두 코드를 돌려 얻은 값과 비교
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

type Ev = any[]; // ["message", 글] · ["tool", 이름, 인자] · ["handoff", 담당, 손님의 마지막 말]
type Appt = { id: string; name: string; phone: string; treatment: string; date: string; time: string };
type Db = { appts: Appt[]; next: number };
type Policy = Record<string, (...a: any[]) => any>;

const TODAY = "2026-11-23"; // 시험은 늘 이 날을 '오늘'로 봄 (월요일)
const WD = "월화수목금토일";
const TREAT: Record<string, string> = { "스케일링": "스케일링", "충치": "충치 치료", "사랑니": "사랑니 발치", "임플란트": "임플란트 상담", "검진": "정기 검진" };
const NUM: Record<string, number> = { "한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "열한": 11, "열두": 12 };
const MIN: Record<string, number> = { "십": 10, "이십": 20, "삼십": 30, "사십": 40, "오십": 50 };
const ORDER = ["treatment", "date", "time", "name", "phone"];
const ASK: Record<string, string> = { treatment: "어떤 진료를 예약해 드릴까요?", date: "원하시는 날짜를 말씀해 주세요.", time: "몇 시가 좋으실까요?",
  name: "예약하실 분의 성함을 말씀해 주세요.", phone: "연락받으실 전화번호를 말씀해 주세요." };
const WHY: Record<string, string> = { closed: "그날은 휴진입니다. 다른 날짜를 말씀해 주세요.", hours: "그 시간은 진료 시간이 아닙니다. 다른 시간을 말씀해 주세요.",
  lunch: "그 시간은 점심시간입니다. 다른 시간을 말씀해 주세요.", unit: "예약은 30분 단위로 받습니다. 정각이나 30분으로 말씀해 주세요.",
  taken: "그 시간에는 이미 예약이 있습니다. 다른 시간을 말씀해 주세요." };
const REASK = ["죄송합니다. 다시 한번 말씀해 주세요.", "잘 알아듣지 못했습니다. 예약, 변경, 취소, 진료 시간 가운데 무엇을 도와드릴까요?"];

const squeeze = (s: string): string => s.replace(/ /g, "");
const pad = (n: number): string => String(n).padStart(2, "0");
const isDigits = (s: string): boolean => /^\d+$/.test(s);
const toDate = (iso: string): Date => new Date(`${iso}T00:00:00Z`);
const addDays = (iso: string, k: number): string => new Date(toDate(iso).getTime() + k * 86400000).toISOString().slice(0, 10);
const weekday = (iso: string): number => (toDate(iso).getUTCDay() + 6) % 7; // 월 0 … 토 5 · 일 6 (Python date.weekday()와 같음)

function newDb(): Db { // 가상의 예약 장부 (시험마다 새로 만듦)
  return { appts: [{ id: "A1", name: "김민준", phone: "01012345678", treatment: "스케일링", date: "2026-11-25", time: "10:00" },
                   { id: "A2", name: "이서연", phone: "01098765432", treatment: "충치 치료", date: "2026-11-23", time: "16:00" },
                   { id: "A3", name: "박지호", phone: "01055556666", treatment: "정기 검진", date: "2026-11-24", time: "14:00" }], next: 4 };
}
const taken = (db: Db, date: string, time: string): boolean => db.appts.some((a) => a.date === date && a.time === time); // 그 날짜 · 시각에 이미 예약이 있는가
const findAppt = (db: Db, last4: string): Appt | null => db.appts.find((a) => a.phone.slice(-4) === last4) ?? null; // 전화번호 뒤 네 자리로 예약 찾기

function koTime(hhmm: string): string { // "15:30" → "오후 3시 30분"
  const [h, m] = hhmm.split(":").map(Number);
  return `${h < 12 ? "오전" : "오후"} ${h <= 12 ? h : h - 12}시` + (m ? ` ${m}분` : "");
}
function koDate(iso: string): string { // "2026-11-25" → "11월 25일 수요일"
  const d = toDate(iso);
  return `${d.getUTCMonth() + 1}월 ${d.getUTCDate()}일 ${WD[weekday(iso)]}요일`;
}

// ── 말에서 정보 뽑기 (받아쓴 글은 띄어쓰기가 없을 수 있으므로 공백을 빼고 찾음) ──
function findDate(text: string, today: string = TODAY): string | null {
  const t = squeeze(text);
  for (const [w, k] of [["오늘", 0], ["내일", 1], ["모레", 2]] as [string, number][]) if (t.includes(w)) return addDays(today, k);
  let m = t.match(/(이번|다음)주([월화수목금토일])요일/);
  if (m) return addDays(today, -weekday(today) + WD.indexOf(m[2]) + (m[1] === "다음" ? 7 : 0));
  m = t.match(/(\d{1,2})월(\d{1,2})일/);
  if (m) { // 없는 날짜("2월 30일")는 '날짜 모름'(null)으로
    const iso = `${today.slice(0, 4)}-${pad(Number(m[1]))}-${pad(Number(m[2]))}`, d = toDate(iso);
    return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === iso ? iso : null;
  }
  m = t.match(/([월화수목금토일])요일/);
  if (m) return addDays(today, ((WD.indexOf(m[1]) - weekday(today) - 1) % 7 + 7) % 7 + 1); // 다가오는 그 요일
  return null;
}

function findTime(text: string): string | null {
  const t = squeeze(text);
  let out: string | null = null;
  for (const m of t.matchAll(/(오전|오후|아침|저녁)?(\d{1,2}|열한|열두|다섯|여섯|일곱|여덟|아홉|한|두|세|네|열)시(반|(\d{1,2}|[이삼사오]?십)분)?/g)) {
    let h = isDigits(m[2]) ? Number(m[2]) : NUM[m[2]];
    const mi = m[3] === "반" ? 30 : m[4] ? (isDigits(m[4]) ? Number(m[4]) : MIN[m[4]] ?? 0) : 0;
    if (((m[1] === "오후" || m[1] === "저녁") && h < 12) || (m[1] === undefined && h <= 6)) h += 12; // 그냥 '3시'는 병원 시간으로 15시
    out = `${pad(h)}:${pad(mi)}`;
  }
  return out;
}

const findTreatment = (text: string): string | null => Object.entries(TREAT).find(([k]) => text.includes(k))?.[1] ?? null;

function findName(text: string, awaiting = false): string | null {
  const t = squeeze(text);
  const SUF = "(?:이라고합니다|라고합니다|이라고|라고|입니다|이에요|예요|이고|인데요|이요|요)";
  let m = t.match(new RegExp("(?:이름은|성함은|저는)([가-힣]{2,4}?)" + SUF));
  if (!m && awaiting) m = t.match(new RegExp("^([가-힣]{2,4}?)" + SUF)) ?? t.match(/^([가-힣]{2,4})[.!?]*$/);
  return m && !["네", "예", "아니", "아니요", "맞아", "글쎄", "그게"].includes(m[1]) ? m[1] : null;
}

const KO_DIGIT = "공일이삼사오육칠팔구";
const digits = (s: string): string => [...s.replace(/영/g, "공")].map((c) => (KO_DIGIT.includes(c) ? String(KO_DIGIT.indexOf(c)) : c)).join("");

function findPhone(text: string): string | null {
  const t = squeeze(text).replace(/\d{1,2}시|\d{1,2}분|\d{1,2}월|\d{1,2}일/g, "");
  const m = t.match(/01\d-?\d{3,4}-?\d{4}/) ?? t.match(/[공영]일[공영일육칠팔구]-?[공영일이삼사오육칠팔구]{3,4}-?[공영일이삼사오육칠팔구]{4}/);
  return m ? digits(m[0]).replace(/\D/g, "") : null;
}

function findLast4(text: string, awaiting = false): string | null {
  const t = squeeze(text);
  let m = t.match(/(?:끝|뒷|뒤)(?:네)?자리(?:는|가)?(\d{4}|[공영일이삼사오육칠팔구]{4})/);
  if (!m && awaiting) m = t.match(/(?<!\d)(\d{4}|[공영일이삼사오육칠팔구]{4})(?!\d)/);
  return m ? digits(m[1]) : null;
}

function findDay(text: string, today: string = TODAY): string | null { // 진료 시간을 묻는 말에서 요일 종류: "평일" · "토" · "일" · "공휴일" · null(말하지 않음)
  const t = squeeze(text);
  if (t.includes("공휴일") || t.includes("빨간날")) return "공휴일";
  if (t.includes("토요일") || t.includes("주말")) return "토";
  if (t.includes("일요일")) return "일";
  if (t.includes("평일") || /[월화수목금]요일/.test(t)) return "평일";
  for (const [w, k] of [["오늘", 0], ["내일", 1], ["모레", 2]] as [string, number][]) if (t.includes(w)) return ["평일", "평일", "평일", "평일", "평일", "토", "일"][weekday(addDays(today, k))];
  return null;
}

function findIntent(text: string): string | null {
  const t = squeeze(text);
  const has = (...ws: string[]): boolean => ws.some((w) => t.includes(w));
  if (has("취소")) return "cancel";
  if (has("변경", "바꾸", "바꿔", "옮기", "옮겨", "미루", "미뤄")) return "change";
  if (has("진료시간", "몇시까지", "몇시부터", "언제까지", "문여", "진료하", "진료해", "하나요", "하세요", "여나요", "쉬나요") && !t.includes("예약")) return "hours";
  if (t.includes("예약") || findTreatment(t)) return "book";
  return null;
}

const YES = ["네", "예", "맞", "그래", "좋아", "응"], NO = ["아니", "아뇨", "틀려", "틀렸", "그대로두", "그만"];
const anyIn = (t: string, ws: string[]): boolean => ws.some((w) => t.includes(w));
const isYes = (t: string): boolean => anyIn(t.replace(/예약/g, ""), YES); // '예약'의 '예'를 동의로 읽지 않게

class Call { // 통화 한 건: run(손님의 말) → 그 턴에 일어난 일들
  p: Policy; db: Db; today: string; s: any;
  log: string[] = []; events: Ev[] = []; ended: string | null = null;
  constructor(policy: Policy, db?: Db, today: string = TODAY) {
    this.p = policy; this.db = db ?? newDb(); this.today = today;
    this.s = { intent: null, slots: {}, stage: null, fails: 0, appt: null, who: {} };
  }
  names(): string[] { return [this.s.slots.name, this.s.who.name, this.s.appt?.name].filter((n) => n); }
  out(evs: Ev[]): Ev[] { // 이 턴의 일들을 기록 (로그에는 정책의 mask_log를 거친 글만 남김)
    for (const e of evs) {
      this.events.push(e);
      if (e[0] === "message") this.log.push("agent: " + this.p.mask_log(e[1], this.names()));
      else if (e[0] === "tool") this.log.push("tool: " + this.p.mask_log(`${e[1]} ${pyDict(e[2])}`, this.names()));
      else if (e[0] === "handoff") { this.log.push(`handoff: ${e[1]} · ${e[2]}`); this.ended = e[1]; }
    }
    return evs;
  }
  start(): Ev[] { return this.out([["message", this.p.greeting()]]); }
  handoff(target: string, msg: string, text: string): Ev[] {
    return [["message", msg], ["handoff", target, "손님의 마지막 말: " + this.p.mask_log(text, this.names())]];
  }
  fail(text: string): Ev[] {
    this.s.fails += 1;
    if (this.p.needs_human(this.s.fails, text)) return this.handoff("human", "상담원에게 연결해 드리겠습니다. 잠시만 기다려 주세요.", text);
    return [["message", REASK[Math.min(this.s.fails, REASK.length) - 1]]];
  }
  slotOk(sl: Record<string, string>): Ev[] | null { // 날짜 · 시각이 다 있으면 정책의 check_slot으로 확인 → 안 되면 까닭을 말하고 다시 받음
    const code = this.p.check_slot(sl.date, sl.time, this.db);
    if (code === "ok") return null;
    delete sl.time;
    if (code === "closed") delete sl.date;
    return [["message", WHY[code] ?? WHY.hours]];
  }
  verify(text: string): Ev[] | null { // 변경 · 취소 전의 본인 확인: 성함 + 전화번호 뒤 네 자리
    const who = this.s.who, n = findName(text, true), l4 = findLast4(text, true);
    if (n) who.name = n;
    if (l4) who.last4 = l4;
    if (!("name" in who) || !("last4" in who)) {
      if (this.s.stage === "who" && !(n || l4)) return this.fail(text);
      this.s.stage = "who"; return [["message", "본인 확인을 위해 예약하신 분의 성함과 전화번호 뒤 네 자리를 말씀해 주세요."]];
    }
    const appt = findAppt(this.db, who.last4);
    if (!this.p.verify_caller(appt, who.name, who.last4)) return this.handoff("human", "본인 확인이 되지 않았습니다. 상담원에게 연결해 드리겠습니다.", text);
    this.s.appt = appt; this.s.stage = "verified"; return null;
  }
  run(text: string): Ev[] {
    if (this.ended) return [];
    const s = this.s, t = squeeze(text);
    const got: Record<string, string> = {};
    for (const [k, v] of [["treatment", findTreatment(t)], ["date", findDate(t, this.today)], ["time", findTime(t)], ["phone", findPhone(t)]]) if (v) got[k as string] = v as string;
    if (s.intent === "book" && s.ask === "name" && findName(text, true)) got.name = findName(text, true) as string;
    else if (findName(text)) got.name = findName(text) as string;
    if (s.intent === "book") Object.assign(s.slots, got);
    const nw0 = findIntent(t), eff = nw0 && nw0 !== s.intent && s.stage !== "confirm" ? nw0 : s.intent;
    const whoSay = (eff === "change" || eff === "cancel") && (eff !== s.intent || s.stage === null || s.stage === "who") ? findName(text, true) : null; // 본인 확인 발화의 이름도 로그에 쓰기 전에 가림
    this.log.push("user: " + this.p.mask_log(text, [...this.names(), ...("name" in got ? [got.name] : []), ...(whoSay ? [whoSay] : [])]));
    if (this.p.needs_human(s.fails, text)) return this.out(this.handoff("human", "상담원에게 연결해 드리겠습니다. 잠시만 기다려 주세요.", text));
    if (this.p.is_billing(text)) return this.out(this.handoff("billing", "수납 담당자에게 연결해 드리겠습니다. 잠시만 기다려 주세요.", text));
    const nw = findIntent(t);
    if (nw && nw !== s.intent && s.stage !== "confirm") {
      Object.assign(s, { intent: nw, stage: null, slots: nw === "book" ? { ...got } : {}, who: {}, appt: null }); delete s.ask;
    }
    const ev = this.dispatch(t, text, got);
    if (!(ev.length && ev[0][0] === "message" && REASK.includes(ev[0][1]))) s.fails = !(ev.length && ev[ev.length - 1][0] === "handoff") ? 0 : s.fails;
    return this.out(ev);
  }
  dispatch(t: string, text: string, got: Record<string, string>): Ev[] {
    switch (this.s.intent) {
      case "hours": return this.hours(t);
      case "book": return this.book(t, text, got);
      case "change": return this.change(t, text, got);
      case "cancel": return this.cancel(t, text);
      default: return this.fail(text);
    }
  }
  hours(t: string): Ev[] { this.s.intent = null; return [["message", this.p.hours_answer(findDay(t, this.today))]]; }
  book(t: string, text: string, got: Record<string, string>): Ev[] {
    const s = this.s, sl = s.slots;
    if (s.stage === "confirm") {
      if (anyIn(t, NO)) { s.stage = null; delete sl.time; return [["message", "알겠습니다. 원하시는 시간을 다시 말씀해 주세요."]]; }
      if ("date" in got || "time" in got) s.stage = null; // 확인 단계에서 날짜 · 시각을 고쳐 말하면 '네'가 섞여 있어도 예약하지 않고 다시 검사
      else if (isYes(t)) {
        const args: Record<string, string> = {};
        for (const k of ORDER) args[k] = sl[k];
        this.db.appts.push({ id: `A${this.db.next}`, ...args } as Appt); this.db.next += 1; s.intent = null; s.stage = null;
        return [["tool", "book", args], ["message", `예약되었습니다. ${koDate(args.date)} ${koTime(args.time)}에 뵙겠습니다.`]];
      } else {
        if (!Object.keys(got).length) return this.fail(text);
        s.stage = null;
      }
    }
    if (!Object.keys(got).length && s.ask) return this.fail(text);
    if ("date" in sl && "time" in sl) { const bad = this.slotOk(sl); if (bad) return bad; }
    const miss = ORDER.find((k) => !(k in sl));
    if (miss) { s.ask = miss; return [["message", ASK[miss]]]; }
    s.stage = "confirm"; delete s.ask;
    return [["message", `${koDate(sl.date)} ${koTime(sl.time)}, ${sl.treatment}, ${sl.name} 님으로 예약할까요?`]];
  }
  change(t: string, text: string, got: Record<string, string>): Ev[] {
    const s = this.s;
    if (s.stage === null || s.stage === "who") {
      const bad = this.verify(text); if (bad) return bad;
      s.new = {}; return [["message", `${koDate(s.appt.date)} ${koTime(s.appt.time)} 예약을 찾았습니다. 언제로 바꿔 드릴까요?`]];
    }
    const nw = s.new;
    if (s.stage === "confirm") {
      if (anyIn(t, NO)) { s.stage = "verified"; s.new = {}; return [["message", "알겠습니다. 원하시는 날짜와 시간을 다시 말씀해 주세요."]]; }
      if (isYes(t)) {
        const a = s.appt; a.date = nw.date; a.time = nw.time; s.intent = null; s.stage = null;
        return [["tool", "reschedule", { id: a.id, date: nw.date, time: nw.time }], ["message", `${koDate(nw.date)} ${koTime(nw.time)}로 변경되었습니다.`]];
      }
      return this.fail(text);
    }
    for (const k of ["date", "time"]) if (k in got) nw[k] = got[k];
    if (!("date" in got || "time" in got)) return this.fail(text);
    if (!("date" in nw)) return [["message", ASK.date]];
    if (!("time" in nw)) return [["message", ASK.time]];
    const bad = this.slotOk(nw); if (bad) return bad;
    s.stage = "confirm"; return [["message", `${koDate(nw.date)} ${koTime(nw.time)}로 바꿀까요?`]];
  }
  cancel(t: string, text: string): Ev[] {
    const s = this.s;
    if (s.stage === null || s.stage === "who") {
      const bad = this.verify(text); if (bad) return bad;
      const a = s.appt;
      if (!this.p.can_cancel(a.date, this.today)) return this.handoff("human", "당일 예약의 취소는 상담원이 도와드립니다. 연결해 드리겠습니다.", text);
      s.stage = "confirm"; return [["message", `${koDate(a.date)} ${koTime(a.time)} ${a.treatment} 예약을 취소할까요?`]];
    }
    if (anyIn(t, NO)) { s.intent = null; s.stage = null; return [["message", "예약을 그대로 두겠습니다."]]; }
    if (isYes(t)) {
      const a = s.appt; this.db.appts.splice(this.db.appts.indexOf(a), 1); s.intent = null; s.stage = null;
      return [["tool", "cancel", { id: a.id }], ["message", "예약이 취소되었습니다."]];
    }
    return this.fail(text);
  }
}
const pyDict = (o: Record<string, string>): string => "{" + Object.entries(o).map(([k, v]) => `'${k}': '${v}'`).join(", ") + "}"; // 로그에 찍는 모양(Python 딕셔너리처럼)

// ── 시험 실행기 ──
type Check = any[];
type TestCase = { id?: string; req: string; title?: string; voice?: boolean; say: string[]; expect: Check[] };

function runTest(test: TestCase, policy: Policy, speak?: (s: string) => string): [boolean, Call] { // 시험 하나 → (통과했는가, 통화 기록)
  const call = new Call(policy); const turns: Ev[][] = [call.start()];
  for (const u of test.say) turns.push(call.run(test.voice && speak ? speak(u) : u));
  return [test.expect.every((c) => checkOne(c, turns, call)), call];
}

function checkOne(c: Check, turns: Ev[][], call: Call): boolean {
  const kind = c[0], msgs = (evs: Ev[]): string => evs.filter((e) => e[0] === "message").map((e) => e[1]).join(" "), allev = turns.flat();
  if (kind === "says" || kind === "not_says") {
    const k = c[1] as number | string;
    const said = k === "any" ? msgs(allev) : typeof k === "number" && -turns.length <= k && k < turns.length ? msgs(turns[k < 0 ? turns.length + k : k]) : "";
    return kind === "says" ? (c[2] as string[]).every((x) => said.includes(x)) : !(c[2] as string[]).some((x) => said.includes(x));
  }
  if (kind === "tool") return allev.some((e) => e[0] === "tool" && e[1] === c[1] && Object.entries(c[2] as Record<string, string>).every(([k, v]) => e[2][k] === v));
  if (kind === "no_tool") return !allev.some((e) => e[0] === "tool" && e[1] === c[1]);
  if (kind === "handoff") return allev.some((e) => e[0] === "handoff" && e[1] === c[1]);
  if (kind === "no_handoff") return !allev.some((e) => e[0] === "handoff");
  if (kind === "log_lacks") return !call.log.some((line) => (c[1] as string[]).some((x) => line.includes(x)));
  if (kind === "log_has") return (c[1] as string[]).every((x) => call.log.some((line) => line.includes(x)));
  throw new Error(`모르는 확인 종류: ${kind}`);
}

function validCheck(c: any): boolean { // 확인 한 줄의 모양이 맞는가 (says 의 검색어 목록이 비면 아무 말에나 통과하므로 안 됨)
  if (!Array.isArray(c) || c.length === 0) return false;
  const words = (x: unknown): boolean => Array.isArray(x) && x.length >= 1 && x.every((w) => typeof w === "string" && w !== "");
  const k = c[0];
  if (k === "says" || k === "not_says") return c.length === 3 && (c[1] === "any" || Number.isInteger(c[1])) && words(c[2]);
  if (k === "tool") return c.length === 3 && typeof c[1] === "string" && typeof c[2] === "object" && c[2] !== null && !Array.isArray(c[2]);
  if (k === "no_tool") return c.length === 2 && typeof c[1] === "string";
  if (k === "handoff") return c.length === 2 && (c[1] === "human" || c[1] === "billing");
  if (k === "no_handoff") return c.length === 1;
  if (k === "log_lacks" || k === "log_has") return c.length === 2 && words(c[1]);
  return false;
}
function validTest(t: any): boolean { // 시험의 모양이 맞는가
  return typeof t === "object" && t !== null && typeof t.req === "string" && Array.isArray(t.say) && t.say.every((u: unknown) => typeof u === "string")
    && Array.isArray(t.expect) && t.expect.length >= 1 && t.expect.every(validCheck);
}

const STARTER: Policy = { // 아직 쓰지 않은 정책의 자리를 맡는 '기본 동작' (일부러 허술함)
  greeting: () => "안녕하세요. 한빛치과입니다. 무엇을 도와드릴까요?",
  hours_answer: (_day: string | null) => "진료 시간은 오전 9시부터 오후 6시까지입니다.",
  check_slot: (_d: string, _t: string, _db: Db) => "ok",
  needs_human: (_fails: number, _text: string) => false,
  verify_caller: (appt: Appt | null, _name: string, _last4: string) => appt !== null,
  is_billing: (_text: string) => false,
  mask_log: (text: string, _names: string[] = []) => text,
  can_cancel: (_appt: string, _today: string) => true,
};

function makePolicy(funcs: Policy): Policy { // 내가 쓴 함수가 오류를 내거나 null(아직 안 씀)을 돌려주면 기본 동작으로 대신함 → 통화는 늘 끝까지 감
  const out: Policy = {};
  for (const name of Object.keys(STARTER)) {
    out[name] = (...a: any[]) => {
      let r: any = null;
      try { r = funcs[name] ? funcs[name](...a) : null; } catch { r = null; }
      return r === null || r === undefined ? STARTER[name](...a) : r;
    };
  }
  return out;
}


// ── 고객의 참고 구현: 정책 함수 8개 (T1 ~ T8) ──
function greeting(): string {
  return "안녕하세요. 한빛치과 AI 상담원 하나입니다. 이 통화는 상담 품질 향상을 위해 녹음됩니다. 무엇을 도와드릴까요?";
}

function hoursAnswer(day: string | null): string {
  const table: Record<string, string> = {
    "평일": "평일은 오전 9시부터 오후 6시까지 진료하고, 점심시간은 오후 1시부터 오후 2시까지입니다.",
    "토": "토요일은 오전 9시부터 오후 1시까지 진료하며 점심시간은 없습니다.",
    "일": "일요일은 휴진입니다.", "공휴일": "공휴일은 휴진입니다." };
  if (day === null) return table["평일"] + " " + table["토"] + " 일요일과 공휴일은 휴진입니다.";
  return table[day];
}

const HOLIDAYS = ["2026-12-25", "2027-01-01"]; // 공휴일(휴진): 요구서 R2 · 실제 병원이면 달력에서 가져옴

function checkSlot(date: string, time: string, db: Db): string {
  const wd = weekday(date); const [h, m] = time.split(":").map(Number); const t = h * 60 + m;
  if (wd === 6 || HOLIDAYS.includes(date)) return "closed";
  const last = wd === 5 ? 12 * 60 + 30 : 17 * 60 + 30;
  if (t < 9 * 60 || t > last) return "hours";
  if (wd < 5 && 13 * 60 <= t && t < 14 * 60) return "lunch";
  if (m !== 0 && m !== 30) return "unit";
  if (taken(db, date, time)) return "taken";
  return "ok";
}

function needsHuman(fails: number, text: string): boolean {
  const t = squeeze(text);
  return fails >= 3 || ["상담원", "사람", "직원"].some((w) => t.includes(w));
}

function verifyCaller(appt: Appt | null, name: string, last4: string): boolean {
  return appt !== null && appt.name === name && appt.phone.slice(-4) === last4;
}

function isBilling(text: string): boolean {
  const t = squeeze(text);
  return ["수납", "결제", "영수증", "환불", "보험", "진료비"].some((w) => t.includes(w));
}

function maskLog(text: string, names: string[] = []): string {
  let out = text.replace(/(01\d)-?\d{3,4}-?(\d{4})/g, "$1-****-$2");
  for (const n of names) out = out.split(n).join(n[0] + "*".repeat(n.length - 1));
  return out;
}

function canCancel(apptDate: string, today: string): boolean {
  return apptDate > today;
}

// 정책 이름은 엔진이 부르는 이름(snake_case) 그대로
const REF: Policy = { greeting, hours_answer: hoursAnswer, check_slot: checkSlot, needs_human: needsHuman,
  verify_caller: verifyCaller, is_billing: isBilling, mask_log: maskLog, can_cancel: canCancel };

