// ── 정리 퀴즈: 오늘 배운 규칙 8문항, 정답은 모두 코드를 돌려 얻은 값과 비교 ──
const empty = newDb();
const STARTER_POLICY = makePolicy({});
const TIMES: string[] = [];
for (let h = 8; h < 19; h++) for (const m of [0, 30]) TIMES.push(`${pad(h)}:${pad(m)}`);

const satLast = (): string => TIMES.filter((t) => checkSlot("2026-11-28", t, empty) === "ok").sort().pop() as string;
const lunchTimes = (): string[] => TIMES.filter((t) => checkSlot("2026-11-24", t, empty) === "lunch");
const starterFailures = (): number => HIDDEN.filter((t) => !runTest(t, STARTER_POLICY)[0]).length;
const failsToHandoff = (): number => { let f = 0; while (!needsHuman(f, "음")) f++; return f; };

const QUIZ: [string, unknown, () => unknown][] = [
  ["Q1. 토요일에 받는 마지막 예약 시각은?", "12:30", satLast],
  ["Q2. 평일에 '점심시간'으로 거절되는 시각은? (30분 단위)", ["13:00", "13:30"], lunchTimes],
  ["Q3. 시험 속의 오늘(2026-11-23)은 무슨 요일?", "월", () => WD[weekday(TODAY)]],
  ["Q4. 오늘 예약(11월 23일)을 AI가 자동으로 취소해도 될까?", false, () => canCancel("2026-11-23", TODAY)],
  ["Q5. 손님의 말을 연달아 몇 번 알아듣지 못하면 상담원에게 넘기나?", 3, failsToHandoff],
  ["Q6. maskLog('010-1234-5678 김민준', ['김민준']) 의 결과는?", "010-****-5678 김**", () => maskLog("010-1234-5678 김민준", ["김민준"])],
  ["Q7. 정책을 하나도 안 쓴 기본 동작은 인수 시험 20개 중 몇 개에서 떨어지나?", 15, starterFailures],
  ["Q8. '진료비가 궁금해요'는 누구에게 넘기나? (human / billing / 안 넘김)", "billing", () => (isBilling("진료비가 궁금해요") ? "billing" : needsHuman(0, "진료비가 궁금해요") ? "human" : "안 넘김")],
];
let score = 0;
for (const [q, want, compute] of QUIZ) {
  const got = compute();
  const ok = same(got, want);
  score += Number(ok);
  console.log(`${ok ? "O" : "X"} ${q}  → ${Array.isArray(got) ? JSON.stringify(got) : got}`);
}
console.log(`정리 퀴즈 ${score} / ${QUIZ.length}`);
check(QUIZ.length === 8 && score === 8, "퀴즈 8문항의 정답이 코드를 돌려 얻은 값과 모두 같아야 해요.");
